<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\{PeriodGuard,AcademicRules,AcademicDebtService};
class AttestationController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head')||$r->user()->canDo('semester.mark'),403);}
 public function index(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$sheets=DB::table('attestation_sheets as a')->join('study_groups as g','g.id','=','a.study_group_id')->join('subjects as s','s.id','=','a.subject_id')->leftJoin('teachers as t','t.id','=','a.teacher_id')->where('a.academic_period_id',$p->id)->select('a.*','g.name as group_name','s.name as subject_name','t.last_name','t.first_name')->orderByDesc('a.id')->get();foreach($sheets as $x){$studentIds=DB::table('attestation_attempts')->where('attestation_sheet_id',$x->id)->distinct()->pluck('student_id');$x->debts=0;foreach($studentIds as $sid){$last=DB::table('attestation_attempts')->where(['attestation_sheet_id'=>$x->id,'student_id'=>$sid])->orderByDesc('attempt_no')->first();if($last&&$last->completed_at&&!$last->passed)$x->debts++;}}$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get();$subjects=DB::table('subjects')->orderBy('name')->get();$teachers=DB::table('teachers')->where('active',1)->orderBy('last_name')->get();return view('attestation.index',compact('p','sheets','groups','subjects','teachers'));}
 public function debts(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$all=DB::table('attestation_attempts as x')->join('attestation_sheets as a','a.id','=','x.attestation_sheet_id')->join('students as s','s.id','=','x.student_id')->join('study_groups as g','g.id','=','a.study_group_id')->join('subjects as sub','sub.id','=','a.subject_id')->where('a.academic_period_id',$p->id)->select('x.*','a.assessment_type','a.number as sheet_number','g.name as group_name','sub.name as subject_name','s.last_name','s.first_name','s.middle_name')->orderBy('s.last_name')->get()->groupBy(fn($x)=>$x->attestation_sheet_id.':'.$x->student_id);$debts=collect();$retakes=collect();foreach($all as $attempts){$sorted=$attempts->sortBy('attempt_no');$last=$sorted->last();$completed=$sorted->whereNotNull('completed_at');if($completed->count()&&!$completed->last()->passed)$debts->push($last);if($last->attempt_no>0&&!$last->completed_at)$retakes->push($last);}return view('attestation.debts',compact('p','debts','retakes'));}
 public function store(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');PeriodGuard::writable($p->id);$d=$r->validate(['study_group_id'=>'required|exists:study_groups,id','subject_id'=>'required|exists:subjects,id','teacher_id'=>'nullable|exists:teachers,id','assessment_type'=>'required|in:exam,credit,differentiated_credit,coursework,other','assessment_date'=>'nullable|date','number'=>'nullable|string|max:100']);$id=DB::transaction(function()use($d,$p,$r){$id=DB::table('attestation_sheets')->insertGetId($d+['academic_period_id'=>$p->id,'status'=>'open','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);$students=DB::table('student_group_memberships')->where(['academic_period_id'=>$p->id,'study_group_id'=>$d['study_group_id'],'status'=>'active'])->pluck('student_id');if(!$students->count())$students=DB::table('students')->where(['current_group_id'=>$d['study_group_id'],'status'=>'active'])->pluck('id');foreach($students as $sid)DB::table('attestation_attempts')->insert(['attestation_sheet_id'=>$id,'student_id'=>$sid,'attempt_no'=>0,'kind'=>'primary','scheduled_on'=>$d['assessment_date']??null,'created_at'=>now(),'updated_at'=>now()]);return $id;});return redirect()->route('attestation.show',$id);}
 public function update(Request $r,$id){$this->ok($r);$a=DB::table('attestation_sheets')->find($id);abort_if(!$a,404);PeriodGuard::writable($a->academic_period_id);abort_if($a->status==='closed',423,'Закрытая ведомость доступна только для чтения. Сначала переоткройте её.');$d=$r->validate(['assessment_date'=>'nullable|date','number'=>'nullable|string|max:100','teacher_id'=>'nullable|exists:teachers,id']);DB::table('attestation_sheets')->where('id',$id)->update($d+['updated_at'=>now()]);return back()->with('success','Параметры ведомости обновлены.');}
 public function close(Request $r,$id){$this->ok($r);$a=DB::table('attestation_sheets')->find($id);abort_if(!$a,404);PeriodGuard::writable($a->academic_period_id);$open=DB::table('attestation_attempts')->where('attestation_sheet_id',$id)->whereNull('completed_at')->count();abort_if($open>0,422,'Нельзя закрыть ведомость: есть незаполненные результаты.');DB::table('attestation_sheets')->where('id',$id)->update(['status'=>'closed','updated_at'=>now()]);return back()->with('success','Ведомость закрыта.');}
 public function reopen(Request $r,$id){$this->ok($r);$a=DB::table('attestation_sheets')->find($id);abort_if(!$a,404);PeriodGuard::writable($a->academic_period_id);DB::table('attestation_sheets')->where('id',$id)->update(['status'=>'open','updated_at'=>now()]);return back()->with('success','Ведомость снова открыта.');}
 public function calendar(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$events=DB::table('attestation_attempts as x')->join('attestation_sheets as a','a.id','=','x.attestation_sheet_id')->join('students as s','s.id','=','x.student_id')->join('study_groups as g','g.id','=','a.study_group_id')->join('subjects as sub','sub.id','=','a.subject_id')->where('a.academic_period_id',$p->id)->whereNotNull('x.scheduled_on')->select('x.*','a.assessment_type','a.number as sheet_number','g.name as group_name','sub.name as subject_name','s.last_name','s.first_name','s.middle_name')->orderBy('x.scheduled_on')->orderBy('g.name')->get();return view('attestation.calendar',compact('p','events'));}
 public function bulkResults(Request $r,$id){$this->ok($r);$a=DB::table('attestation_sheets')->find($id);abort_if(!$a,404);PeriodGuard::writable($a->academic_period_id);abort_if($a->status==='closed',423,'Закрытая ведомость доступна только для чтения.');$d=$r->validate(['results'=>'required|array','results.*.result'=>'nullable|string|max:100','results.*.passed'=>'nullable|in:0,1','results.*.reason'=>'nullable|string|max:2000']);DB::transaction(function()use($d,$id,$r){foreach($d['results'] as $attempt=>$v){$x=DB::table('attestation_attempts')->where(['id'=>$attempt,'attestation_sheet_id'=>$id,'attempt_no'=>0])->first();if(!$x||!array_key_exists('passed',$v)||trim((string)($v['result']??''))==='')continue;DB::table('attestation_attempts')->where('id',$attempt)->update(['result'=>$v['result'],'passed'=>(int)$v['passed'],'reason'=>$v['reason']??null,'completed_at'=>now(),'recorded_by'=>$r->user()->id,'updated_at'=>now()]);}});return back()->with('success','Результаты ведомости сохранены.');}
 public function commissionPrint(Request $r,$id){$this->ok($r);$x=DB::table('attestation_attempts as x')->join('attestation_sheets as a','a.id','=','x.attestation_sheet_id')->join('students as s','s.id','=','x.student_id')->join('study_groups as g','g.id','=','a.study_group_id')->join('subjects as sub','sub.id','=','a.subject_id')->where('x.id',$id)->select('x.*','a.number as sheet_number','a.assessment_type','g.name as group_name','sub.name as subject_name','s.last_name','s.first_name','s.middle_name')->first();abort_if(!$x,404);$members=DB::table('attestation_commission_members as m')->leftJoin('teachers as t','t.id','=','m.teacher_id')->where('m.attestation_attempt_id',$id)->select('m.*','t.last_name','t.first_name','t.middle_name')->get();return view('attestation.commission-print',compact('x','members'));}
 public function show(Request $r,$id){$this->ok($r);$a=DB::table('attestation_sheets as a')->join('study_groups as g','g.id','=','a.study_group_id')->join('subjects as s','s.id','=','a.subject_id')->where('a.id',$id)->select('a.*','g.name as group_name','s.name as subject_name')->first();abort_if(!$a,404);$rows=DB::table('attestation_attempts as x')->join('students as s','s.id','=','x.student_id')->where('x.attestation_sheet_id',$id)->select('x.*','s.last_name','s.first_name','s.middle_name')->orderBy('s.last_name')->orderBy('x.attempt_no')->get()->groupBy('student_id');$teachers=DB::table('teachers')->where('active',1)->orderBy('last_name')->get();return view('attestation.show',compact('a','rows','teachers'));}
 public function result(Request $r,$attempt){$this->ok($r);$x=DB::table('attestation_attempts as x')->join('attestation_sheets as a','a.id','=','x.attestation_sheet_id')->where('x.id',$attempt)->select('x.*','a.academic_period_id','a.status as sheet_status')->first();abort_if(!$x,404);PeriodGuard::writable($x->academic_period_id);abort_if($x->sheet_status==='closed',423,'Закрытая ведомость защищена. Сначала переоткройте её.');$d=$r->validate(['result'=>'required|string|max:100','passed'=>'required|boolean','reason'=>'nullable|string|max:2000']);if($x->attempt_no==2 && $d['passed']){$min=max(1,(int)AcademicRules::get('commission_min_members',1));$cnt=DB::table('attestation_commission_members')->where('attestation_attempt_id',$attempt)->count();abort_if($cnt<$min,422,"Для второй пересдачи требуется состав комиссии не менее {$min} чел.");}DB::table('attestation_attempts')->where('id',$attempt)->update($d+['completed_at'=>now(),'recorded_by'=>$r->user()->id,'updated_at'=>now()]);return back()->with('success','Результат сохранён в истории.');}
 public function retake(Request $r,$attempt){$this->ok($r);$x=DB::table('attestation_attempts as x')->join('attestation_sheets as a','a.id','=','x.attestation_sheet_id')->where('x.id',$attempt)->select('x.*','a.academic_period_id')->first();abort_if(!$x,404);PeriodGuard::writable($x->academic_period_id);abort_unless($x->passed===0||$x->passed==='0',422,'Пересдача создаётся только для незакрытой задолженности.');$max=DB::table('attestation_attempts')->where(['attestation_sheet_id'=>$x->attestation_sheet_id,'student_id'=>$x->student_id])->max('attempt_no');abort_if($max>=2,422,'Две повторные попытки уже использованы.');$n=$max+1;$d=$r->validate(['scheduled_on'=>'required|date']);$id=DB::table('attestation_attempts')->insertGetId(['attestation_sheet_id'=>$x->attestation_sheet_id,'student_id'=>$x->student_id,'attempt_no'=>$n,'kind'=>$n===2?'commission':'retake','scheduled_on'=>$d['scheduled_on'],'created_at'=>now(),'updated_at'=>now()]);return redirect()->route('attestation.attempt',$id)->with('success',$n===2?'Создана вторая пересдача: требуется комиссия.':'Создана первая пересдача.');}
 public function attempt(Request $r,$id){$this->ok($r);$x=DB::table('attestation_attempts as x')->join('attestation_sheets as a','a.id','=','x.attestation_sheet_id')->join('students as s','s.id','=','x.student_id')->join('subjects as sub','sub.id','=','a.subject_id')->where('x.id',$id)->select('x.*','a.academic_period_id','a.study_group_id','sub.name as subject_name','s.last_name','s.first_name','s.middle_name')->first();abort_if(!$x,404);$members=DB::table('attestation_commission_members as m')->leftJoin('teachers as t','t.id','=','m.teacher_id')->where('m.attestation_attempt_id',$id)->select('m.*','t.last_name','t.first_name','t.middle_name')->get();$teachers=DB::table('teachers')->where('active',1)->orderBy('last_name')->get();return view('attestation.attempt',compact('x','members','teachers'));}
 public function member(Request $r,$id){$this->ok($r);$x=DB::table('attestation_attempts as x')->join('attestation_sheets as a','a.id','=','x.attestation_sheet_id')->where('x.id',$id)->select('x.*','a.academic_period_id')->first();abort_if(!$x,404);PeriodGuard::writable($x->academic_period_id);abort_unless($x->attempt_no==2,422);$d=$r->validate(['teacher_id'=>'nullable|exists:teachers,id','member_name'=>'nullable|string|max:255','role'=>'required|string|max:100']);abort_if(empty($d['teacher_id'])&&empty($d['member_name']),422,'Укажите члена комиссии.');DB::table('attestation_commission_members')->insert($d+['attestation_attempt_id'=>$id,'created_at'=>now(),'updated_at'=>now()]);return back();}
 public function print(Request $r,$id){$this->ok($r);$a=DB::table('attestation_sheets as a')->join('study_groups as g','g.id','=','a.study_group_id')->join('subjects as s','s.id','=','a.subject_id')->where('a.id',$id)->select('a.*','g.name as group_name','s.name as subject_name')->first();abort_if(!$a,404);$rows=DB::table('attestation_attempts as x')->join('students as s','s.id','=','x.student_id')->where('x.attestation_sheet_id',$id)->select('x.*','s.last_name','s.first_name','s.middle_name')->orderBy('s.last_name')->orderBy('x.attempt_no')->get();return view('attestation.print',compact('a','rows'));}
}